// Only an explicit provider rejection permits another submit. Transport ambiguity does not.
const input = $('Normalize Input').first().json;
const ctx = { tag: input.tag || '', slug: input.slug || '', checkin_id: input.checkin_id || '' };
const unknown = () => [{ json: { ...ctx, success: false, state: 'outcome_unknown', retry_allowed: false } }];
const status = $json.statusCode;
let response = $json.body;
if (!Number.isInteger(status) || status < 200 || status >= 300) return unknown();
if (typeof response === 'string') {
  try { response = JSON.parse(response); } catch (_) { return unknown(); }
}
if (!response || typeof response !== 'object' || Array.isArray(response)) return unknown();
if (Object.prototype.hasOwnProperty.call(response, 'stored_member') && typeof response.stored_member !== 'boolean') return unknown();
if (response.stored_member === true && response.request_result === 'success') {
  return [{ json: { ...ctx, success: true, state: 'accepted', provider_accepted: true } }];
}
const errors = response.member_errors;
const hasErrors = errors && typeof errors === 'object' && !Array.isArray(errors)
  && Object.values(errors).some(value => typeof value === 'string' ? !!value.trim()
    : Array.isArray(value) && value.some(message => typeof message === 'string' && !!message.trim()));
if (response.request_result !== 'fail' || response.stored_member === true || !hasErrors) return unknown();
const aliases = { socialsecuritynumber: 'personnummer', personnummer: 'personnummer', email: 'email', phone1: 'telephone', phone: 'telephone', telephone: 'telephone' };
const fields = {};
for (const [name, value] of Object.entries(errors)) {
  const field = Object.prototype.hasOwnProperty.call(aliases, name) ? aliases[name] : null;
  if (!field) continue;
  const messages = typeof value === 'string' ? [value] : value;
  if (!Array.isArray(messages)) continue;
  const clean = messages.filter(message => typeof message === 'string' && message.trim()).slice(0, 3)
    .map(message => message.trim().slice(0, 200).replace(/(?<!\d)(?:\d{12}|\d{10}|\d{8}[-+]\d{4}|\d{6}[-+]\d{4})(?!\d)/g, '[personal ID]'));
  if (clean.length) fields[field] = [...(fields[field] || []), ...clean].slice(0, 3);
}
return [{ json: { ...ctx, success: false, state: 'rejected', verified_rejection: true,
  request_result: 'fail', retry_allowed: true, field_errors: fields } }];

// An SSE notification is never a local database acknowledgement.
const parsed = $('Parse Response').first().json;
const ack = $('Report Member Status').first().json;
let body = ack.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (_) { body = null; } }
const acknowledged = Number.isInteger(ack.statusCode) && ack.statusCode >= 200 && ack.statusCode < 300
  && body && typeof body === 'object' && body.success === true && body.member === true
  && body.checkin_id === parsed.checkin_id;
return [{ json: acknowledged
  ? { success: true, state: 'registered', registered: true, member: true, provider_accepted: true, retry_allowed: false }
  : { success: false, state: 'local_sync_pending', provider_accepted: true, retry_allowed: false } }];

// Whitelist the public result. Never return provider bodies or execution errors.
const parsed = $('Parse Response').first().json;
return [{ json: parsed.state === 'rejected' && parsed.verified_rejection === true
  ? { success: false, state: 'rejected', verified_rejection: true, request_result: 'fail', retry_allowed: true, field_errors: parsed.field_errors }
  : { success: false, state: 'outcome_unknown', retry_allowed: false } }];
